// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests the all-vendor mirror inside the cloud sync flow
// Flo: three mock vendors + temp Db > sync with the mirror on > assert stores, statements, queues, alerts
// I/O: queued pages > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const flow = @import("ru-clou-flow.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const file = @import("st-stor-file.zig"); const fail = @import("ru-fail-over.zig");
const allo = std.testing.allocator; const NOWZ: i64 = 1795528470301; const DAYZ: i64 = 86400000; const BIGG: u64 = 1 << 30;
const Rigg = struct { tmpz: std.testing.TmpDir, c1zz: cmok.Mock, c2zz: cmok.Mock, c3zz: cmok.Mock, dirz: []u8, rawd: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, stos: [3]flow.Vend, sqls: [3]flow.Vsqd, flwz: flow.Flow, nume: u32 = 0,
fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.rawd = try std.fs.path.join(allo, &.{ self.dirz, "raw" }); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.c1zz = cmok.Mock.init(allo); self.c2zz = cmok.Mock.init(allo); self.c3zz = cmok.Mock.init(allo); self.c3zz.dial = .mysq; self.nume = 0; self.stos = .{ .{ .name = "b2zz", .store = self.c1zz.store(), .capb = BIGG }, .{ .name = "r2zz", .store = self.c2zz.store(), .capb = BIGG }, .{ .name = "tigr", .store = self.c3zz.store(), .capb = BIGG } }; self.sqls = .{ .{ .name = "turs", .sql2 = self.c1zz.sql2(), .capb = BIGG }, .{ .name = "neon", .sql2 = self.c2zz.sql2(), .capb = BIGG }, .{ .name = "tidb", .sql2 = self.c3zz.sql2(), .capb = BIGG } }; self.flwz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .stos = &self.stos, .sqls = &self.sqls }; self.flwz.conf.clou_fail_runs = 1; self.flwz.conf.clou_mirr_enab = true; }
fn down(self: *Rigg) void { self.c1zz.deinit(); self.c2zz.deinit(); self.c3zz.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.rawd); allo.free(self.dirz); self.tmpz.cleanup(); }
fn queu(self: *Rigg) !void { self.nume += 1; const bodz = try std.fmt.allocPrint(self.aren.allocator(), "mirror body number {d}", .{self.nume}); const sav2 = try file.fileSave(allo, std.testing.io, self.rawd, bodz); const hexz = try self.aren.allocator().dupe(u8, &sav2.hexz); try outb.outbAddz(&self.dbzz, "file", hexz, 0, false); const urlz = try std.fmt.allocPrint(self.aren.allocator(), "http://m/{d}", .{self.nume}); try inde.pageSetz(&self.dbzz, urlz, .{ .hexz = hexz, .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = NOWZ, .next = 2 }); try inde.recoSetz(&self.dbzz, urlz, .{ .hexz = hexz, .kind = "text", .body = "b" }, NOWZ); try outb.outbAddz(&self.dbzz, "rec", urlz, 0, false); }
fn runzNumb(_: *Rigg, mock: *cmok.Mock) usize { var cont: usize = 0; var iter = mock.map.keyIterator(); while (iter.next()) |key2| { if (std.mem.startsWith(u8, key2.*, "runs/")) cont += 1; } return cont; }
fn scal(self: *Rigg, sqlz: [:0]const u8) !i64 { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); if (!try stmt.step()) return -1; return stmt.colzIntz(0); } };
test "mirror on: one sync writes the pack to every store and the rows to every database, backfill finishes, nothing is left queued" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); const fres = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("b2zz", fres.stor); try std.testing.expectEqualStrings("turs", fres.sqlv); try std.testing.expect(fres.mirr.onzz); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c1zz)); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c2zz)); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c3zz)); try std.testing.expect(rig3.c1zz.sawzStmt("INTO cl_page") >= 1 and rig3.c2zz.sawzStmt("INTO cl_page") >= 1 and rig3.c3zz.sawzStmt("INTO cl_page") >= 1); try std.testing.expect(rig3.c3zz.sawzStmt("ON DUPLICATE KEY UPDATE") >= 1); try std.testing.expectEqual(@as(usize, 0), rig3.c3zz.sawzStmt("ON CONFLICT")); try std.testing.expectEqual(@as(i64, 0), fres.mirr.left); try std.testing.expectEqual(@as(i64, 0), fres.mirr.sqlf); try std.testing.expectEqual(@as(i64, 1), try fail.flagGetz(&rig3.dbzz, "msql_neon")); try std.testing.expectEqual(@as(i64, 1), try fail.flagGetz(&rig3.dbzz, "msql_tidb")); try std.testing.expectEqual(@as(usize, 0), fres.alrt.len); }
test "a mirror store that is down gives an alert and a queue, the sync still succeeds, the next run copies the pack" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); rig3.c3zz.stoo = true; const rsl1 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("b2zz", rsl1.stor); try std.testing.expectEqual(@as(u8, 1), rsl1.tris); try std.testing.expectEqual(@as(usize, 0), rig3.runzNumb(&rig3.c3zz)); try std.testing.expect(rsl1.mirr.left >= 1); try std.testing.expect(rsl1.mirr.dead >= 1); var seen = false; for (rsl1.alrt) |line| { if (std.mem.indexOf(u8, line, "mirror tigr (store) failed") != null) seen = true; } try std.testing.expect(seen); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "tigr", NOWZ + 1000)); rig3.c3zz.stoo = false; try rig3.queu(); const rsl2 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ + 2 * DAYZ); try std.testing.expectEqual(@as(usize, 2), rig3.runzNumb(&rig3.c1zz)); try std.testing.expectEqual(@as(usize, 2), rig3.runzNumb(&rig3.c3zz)); try std.testing.expectEqual(@as(i64, 0), rsl2.mirr.left); }
test "a mirror database that is down keeps its spool, then catches up in order on the next run" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); rig3.c2zz.sqlo = true; const rsl1 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("turs", rsl1.sqlv); try std.testing.expect(rsl1.mirr.sqlf >= 1); var seen = false; for (rsl1.alrt) |line| { if (std.mem.indexOf(u8, line, "mirror neon (database) failed") != null) seen = true; } try std.testing.expect(seen); rig3.c2zz.sqlo = false; try rig3.queu(); const rsl2 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ + 2 * DAYZ); try std.testing.expectEqual(@as(i64, 0), rsl2.mirr.sqlf); try std.testing.expect(rig3.c2zz.sawzStmt("http://m/1") >= 1 and rig3.c2zz.sawzStmt("http://m/2") >= 1); try std.testing.expectEqual(@as(usize, 0), rsl2.alrt.len); }
test "the main store failing moves the main role to the next vendor, the others still get the pack" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); rig3.c1zz.stoo = true; const fres = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("r2zz", fres.stor); try std.testing.expectEqual(@as(u8, 2), fres.tris); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c2zz)); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c3zz)); try std.testing.expectEqual(@as(usize, 0), rig3.runzNumb(&rig3.c1zz)); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM pack WHERE vend='r2zz';")); }
test "mirror off keeps the old one-vendor behavior exactly" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.flwz.conf.clou_mirr_enab = false; try rig3.queu(); const fres = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expect(!fres.mirr.onzz); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c1zz)); try std.testing.expectEqual(@as(usize, 0), rig3.runzNumb(&rig3.c2zz)); try std.testing.expectEqual(@as(usize, 0), rig3.runzNumb(&rig3.c3zz)); try std.testing.expectEqual(@as(usize, 0), rig3.c2zz.sawzStmt("INTO cl_page")); }
// =======================___THIS_IS_THE_END___=======================
